def load_background():
    with Image.open(BytesIO(b64decode(_BACKGROUND))) as image:
        return image.convert("RGB")


def write_icon(path):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    image = ImageOps.fit(load_background(), (256, 256), centering=(.5, .25))
    image.save(path, format="ICO", sizes=[(16, 16), (24, 24), (32, 32), (48, 48), (64, 64), (128, 128), (256, 256)])
    return path
